import pytest
from fastapi.testclient import TestClient

from app.main import CUSTOMERS, app

client = TestClient(app)


@pytest.fixture(autouse=True)
def restore_customers():
    snapshot = dict(CUSTOMERS)
    yield
    CUSTOMERS.clear()
    CUSTOMERS.update(snapshot)


def test_get_customer():
    r = client.get("/customers/1")
    assert r.status_code == 200
    assert r.json()["name"] == "Ada"


def test_get_customer_not_found():
    assert client.get("/customers/999").status_code == 404


def test_create_customer():
    r = client.post("/customers", json={"name": "Bob", "email": "bob@example.com"})
    assert r.status_code == 201
    body = r.json()
    assert body == {"id": 2, "name": "Bob", "email": "bob@example.com"}
    assert client.get(f"/customers/{body['id']}").json() == body


def test_create_customer_invalid_body():
    r = client.post("/customers", json={"name": "Bob"})
    assert r.status_code == 422


def test_update_customer_email():
    r = client.patch("/customers/1/email", json={"email": "new@example.com"})
    assert r.status_code == 200
    assert r.json() == {"id": 1, "name": "Ada", "email": "new@example.com"}
    assert client.get("/customers/1").json()["email"] == "new@example.com"


def test_update_customer_email_not_found():
    r = client.patch("/customers/999/email", json={"email": "x@example.com"})
    assert r.status_code == 404


def test_update_customer_email_invalid_body():
    assert client.patch("/customers/1/email", json={}).status_code == 422

